/* Choose the thin horizontal box axis, approaching from the authored spawn side.
 * Fixture setup only: the normal collision and trigger runtime handles movement. */
/* Explicit ctf06 vehicle fixture on actual collision floor677 y4.
 * The renderer-only sky platform is deliberately not used as a floor. */
extern uint32_t rf_scene_vehicle_enabled;
int rf_scene_vehicle_test_place(rf_level *level)
{
    static const float position[3]={30,5,-158.5f},basis[9]={-1,0,0,0,1,0,0,0,-1};
    if(!level)return RF_RANGE;
    if(!strcmp(level->entry.name,"L5S3.rfl")){
        /* Wet DEV fixture; host center(-25,-15,0), player outside radius2. */
        const float wet[3]={-25,-15,3.5f};
        memcpy(level->player_position,wet,12);memcpy(level->player_orientation,basis,36);return RF_OK;
    }
    if(strcmp(level->entry.name,"ctf06.rfl"))return RF_RANGE;
    if(rf_scene_vehicle_enabled==5){
        const float side[3]={33,5,-160},look[9]={0,0,1,0,1,0,-1,0,0};
        memcpy(level->player_position,side,12);memcpy(level->player_orientation,look,36);return RF_OK;
    }
    memcpy(level->player_position,position,12);memcpy(level->player_orientation,basis,36);return RF_OK;
}
int rf_scene_stage_exit(rf_level *level,uint32_t uid)
{
    rf_level_trigger_reader reader;rf_level_trigger record;rf_trigger_volume selected={0},volume;
    uint32_t link,i,j,found=0,axis=3;float direction[3],position[3],matrix[3][3]={{0}},dot=0;int status;
    if(!level)return RF_RANGE;
    status=rf_level_triggers_begin(level,&reader);if(status)return status;
    while((status=rf_level_trigger_next(&reader,&record))==RF_OK) {
        uint32_t match=0;
        for(j=0;j<record.link_count;j++){status=rf_level_trigger_link(level,&record,j,&link);if(status)return status;if(link==uid)match=1;}
        if(!match)continue;
        if(found++)return RF_FORMAT;
        status=rf_trigger_volume_init(&record,&volume);if(status)return status;selected=volume;
    }
    if(status!=RF_NOT_FOUND)return status;if(!found)return RF_NOT_FOUND;
    if(selected.shape!=1)return RF_FORMAT;
    for(i=0;i<3;i++)if(fabsf(selected.matrix[i][1])<.01f && (axis==3 || selected.size[i]<selected.size[axis]))axis=i;
    if(axis==3)return RF_FORMAT;
    for(i=0;i<3;i++)dot+=(selected.center[i]-level->player_position[i])*selected.matrix[axis][i];
    for(i=0;i<3;i++){direction[i]=selected.matrix[axis][i]*(dot<0?-1:1);position[i]=selected.center[i]-direction[i]*(selected.size[axis]*.5f+2);}
    direction[1]=0;matrix[0][0]=direction[2];matrix[0][2]=-direction[0];matrix[1][1]=1;memcpy(matrix[2],direction,12);
    memcpy(level->player_position,position,12);memcpy(level->player_orientation,matrix,36);return RF_OK;
}
/* Isolated contact fixture: place the player inside an authored trigger.
 * Does not enable or fire it; normal eligibility, Use and timing still apply. */
int rf_scene_stage_trigger(rf_level *level,uint32_t uid)
{
    rf_level_trigger_reader reader;rf_level_trigger record;int status;
    if(!level)return RF_RANGE;
    status=rf_level_triggers_begin(level,&reader);if(status)return status;
    while((status=rf_level_trigger_next(&reader,&record))==RF_OK)if(record.uid==uid) {
        rf_trigger_volume volume;status=rf_trigger_volume_init(&record,&volume);if(status)return status;
        memcpy(level->player_position,volume.center,12);return RF_OK;
    }
    return status;
}
/* Explicit replay setup, not an authored player-start reconstruction. */
int rf_scene_stage_door(rf_level *level)
{
    rf_geometry_movers movers={0};const rf_geometry_mover *a=NULL,*b=NULL;
    float position[3],matrix[3][3]={{0}};uint32_t i;int status;
    if(!level)return RF_RANGE;
    status=rf_geometry_movers_open(level,1024*1024,&movers);if(status)return status;
    for(i=0;i<movers.count;i++) {
        if(movers.items[i].uid==8544)a=movers.items+i;
        if(movers.items[i].uid==8543)b=movers.items+i;
    }
    if(!a || !b){rf_geometry_movers_close(&movers);return RF_NOT_FOUND;}
    /* The local forward axis is the authored sliding direction, not the
     * doorway normal. Rotate it about world up to approach from the hall. */
    matrix[2][0]=a->orientation[2][2];matrix[2][2]=-a->orientation[2][0];
    for(i=0;i<3;i++)position[i]=(a->position[i]+b->position[i])*.5f-matrix[2][i]*3;
    position[1]+=.625f;matrix[1][1]=1;matrix[0][0]=matrix[2][2];matrix[0][2]=-matrix[2][0];
    memcpy(level->player_position,position,12);memcpy(level->player_orientation,matrix,36);
    rf_geometry_movers_close(&movers);return RF_OK;
}
/* Process-local inspection camera; never changes authored actor placement. */
int rf_scene_stage_item(rf_level *level,uint32_t uid)
{
    rf_level_entity_reader r;rf_level_item item;int status;
    if(!level)return RF_RANGE;status=rf_level_items_begin(level,&r);if(status)return status;
    while((status=rf_level_item_next(&r,&item))==RF_OK)if(item.uid==uid) {
        float direction[3]={0,.4472136f,.8944272f};
        memcpy(level->player_position,item.position,12);level->player_position[2]-=2.5f;level->player_position[1]+=.625f;
        memset(level->player_orientation,0,36);level->player_orientation[0][0]=1;
        level->player_orientation[1][1]=direction[2];level->player_orientation[1][2]=-direction[1];
        memcpy(level->player_orientation[2],direction,12);return RF_OK;
    }
    return status;
}
int rf_scene_stage_actor(rf_level *level,uint32_t uid)
{
    rf_level_entity_reader reader;rf_level_entity actor;uint32_t i;int status;
    if(!level)return RF_RANGE;
    status=rf_level_entities_begin(level,&reader);if(status)return status;
    while((status=rf_level_entity_next(&reader,&actor))==RF_OK)if((uint32_t)actor.uid==uid) {
        float matrix[3][3]={{0}};
        for(i=0;i<3;++i) {
            matrix[2][i]=-actor.orientation[2][i];
            level->player_position[i]=actor.position[i]+actor.orientation[2][i]*3;
        }
        level->player_position[1]+=.625f;
        matrix[1][1]=1;matrix[0][0]=matrix[2][2];matrix[0][2]=-matrix[2][0];
        memcpy(level->player_orientation,matrix,36);return RF_OK;
    }
    return status;
}
int rf_scene_stage_lift(rf_level *level)
{
    rf_geometry_movers movers={0};uint32_t i;int status;
    if(!level)return RF_RANGE;
    status=rf_geometry_movers_open(level,1024*1024,&movers);if(status)return status;
    status=RF_NOT_FOUND;
    for(i=0;i<movers.count;i++)if(movers.items[i].uid==8670) {
        memcpy(level->player_position,movers.items[i].position,12);
        level->player_position[0]-=.5f;
        level->player_position[1]+=.625f;
        memset(level->player_orientation,0,36);
        level->player_orientation[0][0]=level->player_orientation[1][1]=level->player_orientation[2][2]=1;
        status=RF_OK;break;
    }
    rf_geometry_movers_close(&movers);return status;
}
int rf_scene_stage_force(rf_level *level,uint32_t uid)
{
    rf_level_force_reader reader;rf_level_force_region record;int status;
    if(!level)return RF_RANGE;
    status=rf_level_forces_begin(level,&reader);if(status)return status;
    while((status=rf_level_force_next(&reader,&record))==RF_OK)if(record.uid==uid) {
        memcpy(level->player_position,record.position,12);level->player_position[0]+=.125f;
        memset(level->player_orientation,0,36);
        level->player_orientation[0][0]=level->player_orientation[1][1]=level->player_orientation[2][2]=1;
        return RF_OK;
    }
    return status;
}
int rf_scene_stage_climb(rf_level *level,uint32_t mode)
{
    rf_level_entity_reader reader;rf_player_movement_region region;float position[3];uint32_t i;int status;
    if(!level || (mode!=1 && mode!=2))return RF_RANGE;
    status=rf_level_regions_begin(level,&reader);if(status)return status;
    status=rf_level_region_next(&reader,&region);if(status)return status;
    memcpy(position,region.center,12);
    if(mode==2)for(i=0;i<3;++i) {
        float side=(float)(-region.matrix[2][i]*(region.size[2]*.5f+1.0f));
        float up=(float)(region.matrix[1][i]*(1.0f-region.size[1]*.5f));
        position[i]=(float)((double)position[i]+side+up);
    }
    memcpy(level->player_position,position,12);return RF_OK;
}
int rf_scene_replay_header(FILE *file,uint32_t *count,uint32_t *record_size)
{
    long bytes,offset=0;uint32_t header[2],size=24;
    if(!file || !count || !record_size)return RF_RANGE;
    if(fseek(file,0,SEEK_END) || (bytes=ftell(file))<=0 || fseek(file,0,SEEK_SET))return RF_FORMAT;
    if(fread(header,4,1,file)!=1)return RF_FORMAT;
    if(header[0]==0x32494652u || header[0]==0x33494652u || header[0]==0x34494652u || header[0]==0x35494652u || header[0]==0x36494652u) {
        size=header[0]==0x32494652u?28:header[0]==0x33494652u?32:header[0]==0x34494652u?40:header[0]==0x35494652u?44:48;
        if(fread(header+1,4,1,file)!=1 || header[1]!=size)return RF_FORMAT;
        offset=8;
    }
    if(bytes<=offset || (bytes-offset)%size || (bytes-offset)/size>60000 || fseek(file,offset,SEEK_SET))return RF_FORMAT;
    *count=(uint32_t)(bytes-offset)/size;*record_size=size;return RF_OK;
}
