int rf_scene_swim_test_place(rf_level *level)
{
    static const float bodies[3][3]={{100,1,60},{46.4f,-9.5f,19.2f},{43,-5.5f,19.2f}};
    static const float basis[9]={1,0,0,0,1,0,0,0,1};
    uint32_t choice=rf_scene_swim_test_enabled;
    if(!level || choice<1 || choice>3 || strcmp(level->entry.name,choice==1?"L2S3.rfl":"L5S2.rfl"))return RF_FORMAT;
    /* Explicit fixtures only:1 swimming,2 authored lava,3 same-room dry ledge.
     * Exact retained miner spheres pass directional clearance at both lava poses.
     * Body origin copied unchanged; authored eye tags remain in control. */
    memcpy(level->player_position,bodies[choice-1],12);memcpy(level->player_orientation,basis,36);
    return RF_OK;
}
/* Explicit ctf06 developer fixture: east of authored post94, facing west.
 * Standing body origin leaves .01848 clearance above floorY-1.25 using the
 * retained miner's lowest sphere; actual eye offset remains model-owned. */
static uint32_t scene_authored_source_uid=94,scene_authored_source_count=1;
int rf_scene_authored_post_place_source(rf_level *level,uint32_t uid)
{
    static const float position[3]={-2.75f,-.4f,2.5f};
    static const float basis[9]={0,0,1,0,1,0,-1,0,0};
    if(!level || strcmp(level->entry.name,"ctf06.rfl"))return RF_FORMAT;
    if(!rf_geomod_authored_post_detail(uid,NULL) && uid!=108 && uid!=92 && uid!=66 && uid!=93 && uid!=94 && uid!=95 && uid!=96 && uid!=97 && uid!=98)return RF_NOT_FOUND;
    memcpy(level->player_position,position,12);memcpy(level->player_orientation,basis,36);
    if(uid==66){level->player_position[0]=-24;level->player_position[1]=3.6f;level->player_position[2]=8;}
    if(uid==92 || uid==108)level->player_position[2]=0;
    if(uid>=96)level->player_position[0]+=11;
    if(uid==98 || uid==108) { /* Test the east beam from the open room side. */
        level->player_position[0]=3.75f;level->player_orientation[0][2]=-1;level->player_orientation[2][0]=1;
    }
    if(uid==93 || uid==96)level->player_position[2]-=5;
    if(rf_geomod_authored_post_detail(uid,NULL)) {
        level->player_position[2]=(uid==75 || uid==99)?-7.5f:7.5f;
        if(uid==99 || uid==103) {
            level->player_position[0]=3.75f;level->player_orientation[0][2]=-1;level->player_orientation[2][0]=1;
        }
    }
    scene_authored_source_uid=uid;scene_authored_source_count=1;
    return RF_OK;
}
int rf_scene_authored_post_place_group(rf_level *level,uint32_t uid,uint32_t count)
{
    int status;if((rf_geomod_authored_post_detail(uid,NULL) || uid==66) && count!=1)return RF_RANGE;
    if(count!=1 && count!=2 && !(rf_geomod_authored_beam_roof(uid) && count==3))return RF_RANGE;
    status=rf_scene_authored_post_place_source(level,uid);if(status)return status;
    scene_authored_source_count=count;return RF_OK;
}
int rf_scene_authored_post_place(rf_level *level)
{return rf_scene_authored_post_place_source(level,94);}
