/* Both world items and scripted gifts interpret baton weapon counts as cells. */
static int32_t campaign_item_charge(int32_t weapon,int32_t quantity,uint32_t gives_weapon)
{
    if(weapon==campaign_riot_id && gives_weapon && quantity>0) {
        int64_t units=(int64_t)quantity*campaign_weapon_supply.definitions[weapon].magazine;
        return units>INT32_MAX?INT32_MAX:(int32_t)units;
    }
    return quantity;
}
#include "scene_player_shield_pickup.inc"
static int campaign_apply_item_grant(const campaign_item_grant *request)
{
    if(request->weapon==-1) {
        memset(&campaign_player_inventory,0,sizeof(campaign_player_inventory));
        riot_charge_remainder=0;rf_scene_riot[0]=0;
        memset(&combat_trigger,0,sizeof(combat_trigger));combat_trigger.held=!!player_input.fire;
        rf_scene_combat[6]=0;campaign_ammo_publish();return scene_player_shield_damage_sync();
    }
    const rf_weapon_acquire_definition *d=campaign_weapon_supply.definitions+request->weapon;
    int32_t quantity=campaign_item_charge(request->weapon,request->quantity,request->gives_weapon);
    rf_weapon_pickup_grant grant={0};int status=request->weapon==campaign_shield_id?
        scene_player_shield_pickup_grant(&campaign_player_inventory,d,request->weapon,quantity,request->gives_weapon,&grant):
        scene_pickup_shared_ammo_grant(&campaign_player_inventory,&campaign_weapon_supply,request->weapon,quantity,request->gives_weapon,&grant);
    rf_scene_script_grants[7]=(uint32_t)status;if(status)return status;
    ++rf_scene_script_grants[0];rf_scene_script_grants[1]+=grant.acquired;rf_scene_script_grants[2]+=grant.rounds;
    rf_scene_script_grants[3]=(uint32_t)request->weapon;rf_scene_script_grants[4]=campaign_player_inventory.owned[request->weapon];
    rf_scene_script_grants[5]=(uint32_t)campaign_player_inventory.loaded[request->weapon];rf_scene_script_grants[6]=d->ammo_type>=0 && d->ammo_type<32?(uint32_t)campaign_player_inventory.reserve[d->ammo_type]:0;
    campaign_ammo_publish();return request->weapon==campaign_shield_id?scene_player_shield_damage_sync():RF_OK;
}
static int campaign_strip_weapons(void *context)
{
    const campaign_item_grant request={-1,0,0};(void)context;
    if(campaign_startup_inventory_replay){++rf_scene_startup_inventory[1];return RF_OK;}
    if(!campaign_inventory_ready) {
        if(campaign_item_pending_count==32)return RF_RANGE;
        campaign_item_pending[campaign_item_pending_count++]=request;return RF_OK;
    }
    return campaign_apply_item_grant(&request);
}
static int campaign_give_item(void *context,const char *name)
{
    rf_vpp tables={0};rf_item_definition item;campaign_item_grant request;int status;
    if(!context || !name || !name[0])return RF_NOT_FOUND;
    if(campaign_startup_inventory_replay){++rf_scene_startup_inventory[2];return RF_OK;}
    status=rf_vpp_open(&tables,(const char *)context);if(status)return status;
    status=rf_item_definition_load(&tables,name,128*1024,&item);rf_vpp_close(&tables);if(status)return status;
    if(!item.weapon[0] || (item.flags&1))return RF_NOT_FOUND;
    request.weapon=rf_weapon_name_find(&campaign_weapon_supply.names,item.weapon);if(request.weapon<0)return RF_NOT_FOUND;
    request.quantity=item.count;request.gives_weapon=item.gives_weapon;
    if(!campaign_inventory_ready) {
        if(campaign_item_pending_count==32)return RF_RANGE;
        campaign_item_pending[campaign_item_pending_count++]=request;return RF_OK;
    }
    return campaign_apply_item_grant(&request);
}
