                     for(h=0;h<prepared.limit_count;h++)for(j=0;j<3;j++)record->vectors[h][j]=prepared.limits[h].normal[j]*prepared.limits[h].depth;
                     memcpy(s->terrain_requested[s->terrain_history_count],packed,sizeof(packed));
